// Only review when a PR is opened or updated. Pull out what later steps need.
const body = $input.first().json.body;
if (!body || !body.pull_request || !['opened', 'synchronize', 'reopened'].includes(body.action)) {
  return [];
}
return [{ json: {
  repo: body.repository.full_name,
  prNumber: body.pull_request.number,
  prTitle: body.pull_request.title,
  headSha: body.pull_request.head.sha,
} }];

// Keep only Markdown pages that were added or changed.
const pr = $('Keep opened or updated PRs').first().json;
const files = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
return files
  .filter(f => f.filename && f.filename.endsWith('.md') && f.status !== 'removed')
  .slice(0, 10) // cost guard: review at most 10 pages per PR
  .map(f => ({ json: { ...pr, file: f.filename, rawUrl: f.raw_url } }));

// Build the Claude request. Number the lines so every finding can point to one.
const items = $input.all();
const pages = $('Keep Markdown pages').all();
return items.map((item, idx) => {
  const meta = pages[idx].json;
  const numbered = String(item.json.page).split('
').map((l, n) => `${String(n + 1).padStart(4)}  ${l}`).join('
');
  const prompt = `You are reviewing one page of Gravitee product documentation (GitBook Markdown).
A rule-based linter already checks product names, filler words and GitBook syntax - do NOT repeat those.
Only report judgement calls:
- Are prerequisites listed before the first step?
- Is each procedure a numbered list of single actions, with the expected result stated?
- Is any step ambiguous, missing or out of order?
- Are acronyms and jargon explained on first use?
- Do code samples look complete and runnable?
Rules: only report real problems you can point to. Never invent product behaviour - if unsure, write "Check with engineering:". If the page is fine, reply exactly: No issues.
Format: one issue per line as  LINE | problem | suggested fix

Page: ${meta.file}
${numbered}`;
  return { json: { ...meta, claudeBody: {
    model: 'claude-sonnet-4-5',
    max_tokens: 1500,
    messages: [{ role: 'user', content: prompt }]
  } } };
});

// Combine every page's review into ONE pull-request comment (less noise than many comments).
const reviews = $input.all();
const pages = $('Build review prompt').all();
const pr = pages[0].json;
let total = 0;
const sections = reviews.map((r, idx) => {
  const file = pages[idx].json.file;
  const text = (r.json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
  const rows = text.split('\n').map(l => l.split('|').map(s => s.trim())).filter(p => p.length >= 3 && /^\d+$/.test(p[0]));
  total += rows.length;
  if (!rows.length) return `### ${file}\nNo issues found.`;
  const table = rows.map(p => `| ${p[0]} | ${p[1]} | ${p[2]} |`).join('\n');
  return `### ${file}\n| Line | Problem | Suggested fix |\n|---|---|---|\n${table}`;
});
const comment = `## AI docs review\n\n${total} suggestion(s) across ${pages.length} page(s). These are suggestions from Claude - a writer decides what to accept. Style and syntax are checked separately by the docs checker.\n\n${sections.join('\n\n')}`;
return [{ json: { repo: pr.repo, prNumber: pr.prNumber, prTitle: pr.prTitle, total, comment } }];
